from flask import Flask, current_app

def create_app(mode):
    app = Flask(__name__)
    app.config['TESTING'] = True
    app.config['DEMO_MODE'] = mode

    @app.get('/mode')
    def mode_view():
        return {'mode': current_app.config['DEMO_MODE']}

    return app

first = create_app('practice')
second = create_app('review')
assert first is not second
assert first.test_client().get('/mode').json == {'mode': 'practice'}
assert second.test_client().get('/mode').json == {'mode': 'review'}
print('independent app settings')
